def sex_to_dec(s: Any) -> object {
    s = format(int(s), '07d');
    (degree, arcmin, arcsec) = (s[:3], s[3:5], s[5:]);
    return (float(degree) + (float(arcmin) / 60) + (float(arcsec) / 3600));
}

"""Combine import statements.

    Parameters
    ----------
    values : list-like
        The values to be concatenated
    sep : string
        The value between the statements

    Returns
    -------
    str
        The concatenated string

    """
def concat_imports(values: Any, sep: Any = '.') -> object {
    if (len(values) >= 1) {
        store = [];
        for v in values {
            if isinstance(v, (`list, `tuple)) {
                store.extend(v);
            } else {
                store.append(v);
            }
        }
        return sep.join(store);
    } else {
        return '';
    }
}

